class Solution {
public:
    vector<double> sampleStats(vector<int>& count) {
        long long total = 0;
        double min_val = -1.0, max_val = -1.0;
        double sum_val = 0;
        int max_freq = 0;
        double mode_val = 0;

        for (int i = 0; i < 256; ++i) {
            long long c = count[i];
            if (c > 0) {
                if (min_val < 0) min_val = i;
                max_val = i;
                sum_val += (double)i * c;
                total += c;
                if (c > max_freq) {
                    max_freq = c;
                    mode_val = i;
                }
            }
        }

        double mean_val = sum_val / total;
        long long target1 = (total + 1) / 2;
        long long target2 = (total + 2) / 2;
        int med1 = -1, med2 = -1;
        long long cur = 0;
        for (int i = 0; i < 256; ++i) {
            cur += count[i];
            if (med1 == -1 && cur >= target1) med1 = i;
            if (med2 == -1 && cur >= target2) {
                med2 = i;
                break;
            }
        }
        double median_val = (med1 + med2) / 2.0;
        return {min_val, max_val, mean_val, median_val, mode_val};
    }
};

